public boolean canHack(Entity entity, Player player) {
    return entity instanceof Mob mob && IHackableEntity.super.canHack(entity, player)
            && Arrays.stream(EquipmentSlot.values()).anyMatch(slot -> !mob.getItemBySlot(slot).isEmpty());
}

public int getHackTime(Mob entity, Player player) {
    return 60;
}

public void onHackFinished(Mob entity, Player player) {
    if (!entity.level().isClientSide) {
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            if (doDisarm(entity, slot, player.getRandom())) {
                return;
            }
        }
    }
}

private boolean doDisarm(Mob entity, EquipmentSlot slot, RandomSource rand) {
    if (entity.getItemBySlot(slot).isEmpty()) return false;

    MobAccess access = (MobAccess)entity;
    float[] dropChances = slot.getType() == EquipmentSlot.Type.HUMANOID_ARMOR ? access.getArmorDropChances() : access.getHandDropChances();
    int slotIdx = slot.getIndex();
    boolean noDamage = dropChances[slotIdx] > 1f;
    ItemStack stack = entity.getItemBySlot(slot);
    if (!stack.isEmpty() && rand.nextFloat() < dropChances[slotIdx]) {
        if (!noDamage && stack.isDamageableItem()) {
            int k = Math.max(stack.getMaxDamage() - 25, 1);
            int l = stack.getMaxDamage() - rand.nextInt(rand.nextInt(k) + 1);
            stack.setDamageValue(Mth.clamp(l, 1, k));
        }
        entity.spawnAtLocation(stack, 0f);
    }
    entity.setItemSlot(slot, ItemStack.EMPTY);
    return true;
}

public void addHackInfo(Mob entity, List<Component> curInfo, Player player) {
    curInfo.add(xlate("pneumaticcraft.armor.hacking.result.disarm"));
}

public void addPostHackInfo(Mob entity, List<Component> curInfo, Player player) {
    curInfo.add(xlate("pneumaticcraft.armor.hacking.finished.disarmed"));
}

default boolean canHack(Entity entity, Player player) {
    return entity.isAlive() && getHackableClass().isAssignableFrom(entity.getClass());
}

default int _getHackTime(Entity e, Player p) {
    //noinspection unchecked
    return getHackableClass().isAssignableFrom(e.getClass()) ? getHackTime((T) e, p) : -1;
}

default void _onHackFinished(Entity e, Player p) {
    if (getHackableClass().isAssignableFrom(e.getClass())) {
        //noinspection unchecked
        onHackFinished((T) e, p);
    }
}

default boolean afterHackTick(T entity) {
    return false;
}

default void _addHackInfo(Entity e, List<Component> componentList, Player p) {
    if (getHackableClass().isAssignableFrom(e.getClass())) {
        //noinspection unchecked
        addHackInfo((T) e, componentList, p);
    }
}

default void _addPostHackInfo(Entity e, List<Component> componentList, Player p) {
    if (getHackableClass().isAssignableFrom(e.getClass())) {
        //noinspection unchecked
        addPostHackInfo((T) e, componentList, p);
    }
}

public void onTriggered(ICommonArmorHandler armorHandler) {
    if (enabledForPlayer(armorHandler.getPlayer())) {
        ClientArmorRegistry c = ClientArmorRegistry.getInstance();
        c.getClientHandler(CommonUpgradeHandlers.blockTrackerHandler, BlockTrackerClientHandler.class).hack();
        c.getClientHandler(CommonUpgradeHandlers.entityTrackerHandler, EntityTrackerClientHandler.class).hack();
    }
}

public static boolean enabledForPlayer(Player player) {
    return PneumaticArmorItem.isPneumaticArmorPiece(player, EquipmentSlot.HEAD)
            && CommonArmorHandler.getHandlerForPlayer(player).getUpgradeCount(EquipmentSlot.HEAD, ModUpgrades.SECURITY.get()) > 0;
}

public Optional<KeyMapping> getTriggerKeyBinding() {
    return Optional.of(KeyHandler.getInstance().keybindHack);
}

public void hack() {
    getTargetsStream().forEach(RenderEntityTarget::hack);
}

public void hack() {
    if (isInitialized() && isPlayerLookingAtTarget()) {
        Player player = ClientUtils.getClientPlayer();
        IHackableEntity<?> hackable = HackManager.getHackableForEntity(entity, player);
        if (hackable != null && (hackTime == 0 || hackTime > hackable._getHackTime(entity, player)))
            NetworkHandler.sendToServer(new PacketHackingEntityStart(entity.getId()));
    }
}

public boolean isInitialized() {
    return ticksExisted > 120;
}

private boolean isPlayerLookingAtTarget() {
    // code used from the Enderman player looking code.
    Player player = ClientUtils.getClientPlayer();
    Vec3 vec3 = player.getViewVector(1.0F).normalize();
    Vec3 vec31 = new Vec3(entity.getX() - player.getX(), entity.getBoundingBox().minY + entity.getBbHeight() / 2.0F - (player.getY() + player.getEyeHeight()), entity.getZ() - player.getZ());
    double d0 = vec31.length();
    vec31 = vec31.normalize();
    double d1 = vec3.dot(vec31);
    return d1 > 1.0D - 0.025D / d0;
}

public void onHackConfirmServer() {
    hackTime = 1;
}

public int getHackTime() {
    return hackTime;
}

public void tick() {
    stat.tickWidget();
    stat.setTitle(entity.getDisplayName());
    Player player = ClientUtils.getClientPlayer();

    distToEntity = entity.distanceTo(ClientUtils.getClientPlayer());

    if (ticksExisted >= 30 && !didMakeLockSound) {
        didMakeLockSound = true;
        player.level().playLocalSound(player.getX(), player.getY(), player.getZ(), ModSounds.HUD_ENTITY_LOCK.get(), SoundSource.PLAYERS, 0.1F, 1.0F, true);
    }

    boolean tagged = entity instanceof AbstractDroneEntity drone && PneumaticArmorItem.isPlayerDebuggingDrone(player, drone);
    circle1.setRenderingAsTagged(tagged);
    circle1.tick();
    circle2.setRenderingAsTagged(tagged);
    circle2.tick();
    trackEntries.forEach(tracker -> tracker.tick(entity));

    isLookingAtTarget = isPlayerLookingAtTarget();

    if (hackTime > 0) {
        if (HackManager.getHackableForEntity(entity, ClientUtils.getClientPlayer()) != null) {
            hackTime++;
        } else {
            hackTime = 0;
        }
    }
}

public static void handle(PacketHackingEntityStart message, IPayloadContext ctx) {
    Player player = ctx.player();

    if (ctx.flow().isClientbound()) {
        // client
        Entity entity = player.level().getEntity(message.entityId());
        if (entity != null) {
            CommonArmorHandler.getHandlerForPlayer(player)
                    .getExtensionData(CommonUpgradeHandlers.hackHandler)
                    .setHackedEntity(entity);
            ClientArmorRegistry.getInstance()
                    .getClientHandler(CommonUpgradeHandlers.entityTrackerHandler, EntityTrackerClientHandler.class)
                    .getTargetsStream()
                    .filter(target -> target.entity == entity)
                    .findFirst()
                    .ifPresent(RenderEntityTarget::onHackConfirmServer);
        }
    } else if (player instanceof ServerPlayer sp) {
        // server
        CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(player);
        if (handler.upgradeUsable(CommonUpgradeHandlers.entityTrackerHandler, true)) {
            Entity entity = player.level().getEntity(message.entityId());
            if (entity != null) {
                handler.getExtensionData(CommonUpgradeHandlers.hackHandler).setHackedEntity(entity);
                NetworkHandler.sendToPlayer(message, sp);
            }
        }
    }
}

public static PacketHackingEntityFinish forEntity(Entity entity) {
    return new PacketHackingEntityFinish(entity.getId());
}

public static void handle(PacketHackingEntityFinish message, IPayloadContext ctx) {
    Player player = ctx.player();

    Entity entity = player.level().getEntity(message.entityId());
    if (entity != null) {
        IHackableEntity<?> hackableEntity = HackManager.getHackableForEntity(entity, player);
        if (hackableEntity != null) {
            hackableEntity._onHackFinished(entity, player);
            HackTickTracker.getInstance(entity.level()).trackEntity(entity, hackableEntity);
            CommonArmorHandler.getHandlerForPlayer(player).getExtensionData(CommonUpgradeHandlers.hackHandler).setHackedEntity(null);
            player.playSound(ModSounds.HELMET_HACK_FINISH.get(), 1.0F, 1.0F);
        }
    }
}

public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
    Player player = commonArmorHandler.getPlayer();
    if (player instanceof ServerPlayer sp) {
        commonArmorHandler.getExtensionData(this).tickServerSide(sp);
    }
}

private void tickServerSide(ServerPlayer player) {
    if (hackedBlockPos != null) {
        tickBlockHack(player);
    } else if (hackedEntity != null) {
        tickEntityHack(player);
    }
}

private void tickEntityHack(ServerPlayer player) {
    IHackableEntity<?> hackableEntity = HackManager.getHackableForEntity(hackedEntity, player);
    if (hackableEntity != null) {
        int requiredTime = hackableEntity._getHackTime(hackedEntity, player);
        if (requiredTime <= 0) {
            setHackedEntity(null);
            return;
        }
        if (++hackTime >= requiredTime) {
            if (hackedEntity.isAlive()) {
                hackableEntity._onHackFinished(hackedEntity, player);
                HackTickTracker.getInstance(player.level()).trackEntity(hackedEntity, hackableEntity);
                NetworkHandler.sendToAllTracking(PacketHackingEntityFinish.forEntity(hackedEntity), hackedEntity);
                ModCriterionTriggers.ENTITY_HACK.get().trigger(player);
            }
            setHackedEntity(null);
        }
    } else {
        setHackedEntity(null);
    }
}

public void setHackedEntity(Entity entity) {
    hackedEntity = entity;
    hackedBlockPos = null;
    hackTime = 0;
}

private static HackManager getInstance(Level world) {
    if (world.isClientSide) {
        if (clientInstance == null) clientInstance = new HackManager();
        return clientInstance;
    } else {
        if (serverInstance == null) serverInstance = new HackManager();
        return serverInstance;
    }
}

public static IHackableEntity<?> getHackableForEntity(Entity entity, Player player) {
    HackManager manager = getInstance(player.level());

    // prune the tracked entities map every 60 ticks, removing dead or no-longer-hackable entities
    if (player.level().getGameTime() - 60 > manager.lastEntityPrune) {
        manager.hackableEntities.entrySet().removeIf(
                entry -> !entry.getKey().isAlive()
                        || !entry.getValue().canHack(entry.getKey(), player) && !isInDisplayCooldown(entry.getValue(), entry.getKey())
        );
        manager.lastEntityPrune = player.level().getGameTime();
    }

    // entities which implement IHackableEntity directly
    if (entity instanceof IHackableEntity<?> h && h.canHack(entity, player))
        return h;

    // entities which have been registered with the hack manager
    IHackableEntity<?> hackable = manager.hackableEntities.get(entity);
    if (hackable == null) {
        hackable = CommonArmorRegistry.getInstance().getHackable(entity, player);
        if (hackable != null) {
            manager.hackableEntities.put(entity, hackable);
        }
    }
    return hackable;
}

private static boolean isInDisplayCooldown(IHackableEntity<?> hackableEntity, Entity entity) {
    if (entity.level().isClientSide) {
        RenderEntityTarget target = ClientArmorRegistry.getInstance()
                .getClientHandler(CommonUpgradeHandlers.entityTrackerHandler, EntityTrackerClientHandler.class)
                .getTargetForEntity(entity);
        int requiredHackTime = hackableEntity._getHackTime(entity, ClientUtils.getClientPlayer());
        return target != null && target.getHackTime() >= requiredHackTime && target.getHackTime() <= requiredHackTime + 20;
    } else {
        return false;
    }
}

public IHackableEntity<?> getHackable(Entity entity, Player player) {
    if (!hackablesByType.containsKey(entity.getType())) {
        for (var entry : hackableEntities.entrySet()) {
            if (entry.getKey().isAssignableFrom(entity.getClass())) {
                hackablesByType.put(entity.getType(), entry.getValue().get());
            }
        }
    }

    return hackablesByType.get(entity.getType()).stream()
            .filter(hackable -> hackable.canHack(entity, player))
            .findFirst()
            .orElse(null);
}

public void trackEntity(Entity entity, IHackableEntity<?> iHackable) {
    HackManager.getActiveHacks(entity).ifPresent(hacking -> {
        hacking.addHackable(iHackable);
        hackedEntities.add(entity);
    });
}

public boolean isApplicable(Entity entity) {
    return HackClientHandler.enabledForPlayer(ClientUtils.getClientPlayer());
}

public void addInfo(Entity entity, List<Component> curInfo, boolean isLookingAtTarget) {
    Player player = ClientUtils.getClientPlayer();
    IHackableEntity<?> hackable = HackManager.getHackableForEntity(entity, player);
    if (hackable != null && hackable.getHackableClass().isAssignableFrom(entity.getClass())) {
        int hackTime = ClientArmorRegistry.getInstance()
                .getClientHandler(CommonUpgradeHandlers.entityTrackerHandler, EntityTrackerClientHandler.class)
                .getTargetsStream()
                .filter(target -> target.entity == entity)
                .findFirst()
                .map(RenderEntityTarget::getHackTime)
                .orElse(0);
        boolean entityTracked = HackTickTracker.getInstance(entity.level()).isEntityTracked(entity);
        if (hackTime == 0) {
            if (isLookingAtTarget && !entityTracked) {
                hackable._addHackInfo(entity, curInfo, player);
                HackClientHandler.addKeybindTooltip(curInfo);
            }
        } else {
            int requiredHackTime = hackable._getHackTime(entity, player);
            if (requiredHackTime > 0) {
                int percentageComplete = hackTime * 100 / requiredHackTime;
                if (percentageComplete < 100) {
                    curInfo.add(xlate("pneumaticcraft.armor.hacking.hacking", percentageComplete));
                } else if (hackTime < requiredHackTime + 20 || entityTracked) {
                    hackable._addPostHackInfo(entity, curInfo, player);
                } else if (isLookingAtTarget) {
                    hackable._addHackInfo(entity, curInfo, player);
                    HackClientHandler.addKeybindTooltip(curInfo);
                }
            }
        }
    }
}

